function validate([rectangles, points]) {
  if (!Array.isArray(rectangles) || rectangles.length < 1 || rectangles.length > 50000) return 'rectangles needs 1 to 50000 entries.';
  if (!Array.isArray(points) || points.length < 1 || points.length > 50000) return 'points needs 1 to 50000 entries.';
  const okPair = p => Array.isArray(p) && p.length === 2 && Number.isInteger(p[0]) && Number.isInteger(p[1]) && p[0] >= 1 && p[0] <= 1e9 && p[1] >= 1 && p[1] <= 100;
  if (!rectangles.every(okPair)) return 'Each rectangle is [l, h] with 1 <= l <= 10^9 and 1 <= h <= 100.';
  if (!points.every(okPair)) return 'Each point is [x, y] with 1 <= x <= 10^9 and 1 <= y <= 100.';
  if (new Set(rectangles.map(p => p[0] + ',' + p[1])).size !== rectangles.length) return 'All rectangles must be distinct.';
  if (new Set(points.map(p => p[0] + ',' + p[1])).size !== points.length) return 'All points must be distinct.';
  return null;
}

