function countRectangles(rectangles, points) {
  const byHeight = Array.from({ length: 101 }, () => []);
  for (const [length, height] of rectangles) {
    byHeight[height].push(length);
  }
  for (const lengths of byHeight) {
    lengths.sort((a, b) => a - b);
  }

  const count = [];
  for (const [x, y] of points) {
    let total = 0;
    for (let height = y; height <= 100; height++) {
      const lengths = byHeight[height];
      let left = 0;
      let right = lengths.length;
      while (left < right) {
        const mid = (left + right) >> 1;
        if (lengths[mid] < x) {
          left = mid + 1;
        } else {
          right = mid;
        }
      }
      total += lengths.length - left;
    }
    count.push(total);
  }
  return count;
}

