function generate(rand, size) {
  const large = size === 'large';
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const build = (count, maxX, maxY) => {
    const seen = new Set();
    const out = [];
    let tries = 0;
    while (out.length < count && tries < count * 20) {
      tries++;
      const pair = [pick(1, maxX), pick(1, maxY)];
      const key = pair[0] + ',' + pair[1];
      if (seen.has(key)) continue;
      seen.add(key);
      out.push(pair);
    }
    return out;
  };
  if (large) {
    const maxX = rand() < 0.5 ? 1e9 : 5000;
    return [build(2000, maxX, 100), build(2000, maxX, 100)];
  }
  const maxX = rand() < 0.2 ? 1e9 : pick(1, 6);
  const maxY = rand() < 0.2 ? 100 : pick(1, 6);
  return [build(pick(1, 8), maxX, maxY), build(pick(1, 6), maxX, maxY)];
}
